// Minimal Claude client for the judge backend, mirroring gemini.mjs's shape
// ({ name, complete(promptText) }). Uses the same model run-eval.mjs's
// baseline arms were generated with (claude-sonnet-4-5), per
// orchestration-design.md §2's JUDGE_BACKENDS example.
//
// Worth flagging, not resolved here: this means the Claude judge shares a
// model family with the claude_vanilla/claude_web arms it's scoring — the
// exact "no model grades its own homework" problem the two-judge design
// exists to avoid, for those two comparisons specifically (scry isn't
// generated by this model family, so scry-vs-baseline isn't self-graded on
// the scry side). Not changed unilaterally; flag for the eval owner.

const MODEL = "claude-sonnet-4-5";

export function createClaudeBackend(apiKey = process.env.ANTHROPIC_API_KEY) {
  return {
    name: "claude",
    async complete(promptText) {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": apiKey,
          "anthropic-version": "2023-06-01",
        },
        body: JSON.stringify({
          model: MODEL,
          max_tokens: 4096,
          temperature: 0,
          messages: [{ role: "user", content: promptText }],
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(`Claude judge call failed (${res.status}): ${JSON.stringify(data)}`);
      }
      const text = data?.content?.find((b) => b.type === "text")?.text ?? "";
      if (!text) throw new Error(`Claude judge returned no text: ${JSON.stringify(data)}`);
      return text;
    },
  };
}
